var SCRL=[16,20,22,25,30,35,40],FRONTS=[16,18,19,22];
function fixWin(m){var po=N.modules[m.post||m.stem];if(!po||!po.meta||!po.meta.taps)return null;var pm=po.meta,wm=m.washer&&m.washer!=='W0'&&N.modules[m.washer],ws=wm?wm.meta.t:0,em=pm.taps.length>1?8.5:Math.min(8.5,(pm.H-1.2)/2);
 return {a:Math.ceil((ws+5.2)*10-1e-6)/10,b:Math.floor((ws+1.2+em)*10+1e-6)/10,e:Math.floor(em*10+1e-6)/10,w:ws,pin:(pm.pins||[]).length>0};}
function scrPick(t,f){var c=SCRL.filter(function(L){return L>=t+f.a-1e-6&&L<=t+f.b+1e-6;});return c.length?c[c.length-1]:0;}
/* no standard length fits: the set ships screws cut to the right length (24/28 mm where they fit, otherwise the exact length from the CAD window) */
function scrSet(t,f){var c=[24,28].filter(function(L){return L>=t+f.a-1e-6&&L<=t+f.b+1e-6;});if(c.length)return c[0];for(var L=Math.floor(t+f.b+1e-6);L>=Math.ceil(t+f.a-1e-6);L--)return L;return 0;}
